1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	import org.springframework.samples.petclinic.repository.OwnerRepository;
5	
6	/**
7	 * Household membership tier. An owner is {@code GOLD} when three or more owners share its
8	 * {@code householdId}; the SILVER and BRONZE rules (in {@code OwnerMapper}) apply otherwise.
9	 */
10	public final class HouseholdTier {
11	
12	    private HouseholdTier() {
13	    }
14	
15	    /** True when the owner belongs to a household of three or more members. */
16	    public static boolean isGold(Owner owner, OwnerRepository ownerRepository) {
17	        String householdId = owner.getHouseholdId();
18	        if (householdId == null) {
19	            return false;
20	        }
21	        int members = 0;
22	        for (Owner other : ownerRepository.findAll()) {
23	            if (householdId.equals(other.getHouseholdId())) {
24	                members++;
25	            }
26	        }
27	        return members >= 3;
28	    }
29	}
30

1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Records how many existing owners already share this owner's firstName and lastName
9	 * (compared case-insensitively) at creation time, before {@link SaveOwner} runs. The
10	 * new owner is not yet persisted, so {@code findAll()} sees only prior owners.
11	 */
12	public class AssignNamesakeCount {
13	
14	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
15	        String firstName = normalize(owner.getFirstName());
16	        String lastName = normalize(owner.getLastName());
17	        int count = 0;
18	        for (Owner other : ownerRepository.findAll()) {
19	            if (firstName.equals(normalize(other.getFirstName()))
20	                    && lastName.equals(normalize(other.getLastName()))) {
21	                count++;
22	            }
23	        }
24	        owner.setNamesakeCount(count);
25	    }
26	
27	    private static String normalize(String value) {
28	        return value == null ? "" : value.trim().toLowerCase();
29	    }
30	}
